SELECT id, country, rating, LEAD(rating, 1) OVER (PARTITION BY city, country ORDER BY rating, id) AS next_rating, SUM(rating) OVER (ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_rating, LAST_VALUE(city) IGNORE NULLS OVER (PARTITION BY country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_city, RANK() OVER (PARTITION BY country, city ORDER BY rating NULLS FIRST) AS rating_rank, ROW_NUMBER() OVER (ORDER BY rating DESC, id) AS seq_no FROM suppliers;
